import{_ as t,o as n,c as s,a5 as i}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-management/3-10-11-view-revenue-dasboard/report3_spec_en.md","filePath":"feature/admin-management/3-10-11-view-revenue-dasboard/report3_spec_en.md"}'),r={name:"feature/admin-management/3-10-11-view-revenue-dasboard/report3_spec_en.md"};function a(o,e,l,c,d,p){return n(),s("div",null,[...e[0]||(e[0]=[i("<p><strong>3.10.11 View Revenue Dashboard</strong></p><p><strong>Function Trigger</strong></p><p>Begins when an Administrator (ADMIN) accesses financial management at route /admin/revenue.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: ADMIN. System administrator tracking platform-wide revenue streams and payment transaction data.</li><li><strong>Purpose</strong>: Display detailed revenue analytics from recurring subscription service plans (PayOS) and ad-hoc AI Credit token purchases.</li><li><strong>Interface</strong>: Platform Revenue Dashboard (SCR-ADM-10), featuring revenue KPI cards (MRR, ARR, Cumulative Gross Revenue), revenue trend charts over time, revenue breakdown distribution, and recent payment transaction ledger.</li><li><strong>Data Processing</strong>: Verify ADMIN; calculate subscription MRR/ARR from active paid entitlements and separately aggregate reconciled payments/refunds using the selected reporting timezone. Apply current discounts and existing subscription plan catalog.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Revenue Dashboard Screen (SCR-ADM-10, financial analytics grid layout):</p><ul><li>Left/Header: Admin navigation, period filters, timezone UTC / Asia/Ho_Chi_Minh (default), and Export PDF.</li><li>Center: Cards: MRR, ARR, gross receipts, refunds, net receipts and successful transaction count. Separate subscription and AI Credit receipts in charts; catalog plan filter; payment/refund history with status. Clearly distinguish snapshot MRR from period receipts.</li><li>Buttons: Button &quot;Refresh Data&quot;, Time Filter (This Month, This Quarter, This Year, Custom Range), Button &quot;Export Financial PDF Report&quot;.</li><li>Footer: Last financial reconciliation timestamp and payment security compliance advisory.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: None (defaults to current month data).</li><li><strong>Input optional</strong>: period, startDate, endDate, timezone (UTC/Asia/Ho_Chi_Minh), planId (catalog).</li><li><strong>System data</strong>: mrrAmount, arrAmount, grossReceipts, refunds, netReceipts, subscriptionReceipts, aiCreditReceipts, successfulTransactionCount, transactions, asOf, timezone.</li><li><strong>Output</strong>: Platform revenue analytics JSON payload with HTTP status code 200 OK.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-65</strong>: Only ADMIN accesses platform financial data.</li><li><strong>BR-60</strong>: MRR is the monthly-normalized value of active paid subscriptions after applicable discounts; annual plans contribute annual price / 12. ARR = MRR × 12. Gross receipts include successful subscription and one-off AI Credit payments in the period. Show refunds separately; net receipts = gross receipts − refunds. AI Credits are excluded from MRR. Refunds change MRR only when subscription value/status changes; never deduct them twice.</li><li><strong>BR-60</strong>: Use actual successful payment and refund events, including partial refunds. A refunded payment remains in gross receipts; its refund appears separately at refund time. Failed/pending payments contribute nothing.</li><li><strong>BR-60</strong>: Pending Admin plan changes have no immediate MRR, quota or receipts effect. Next-cycle changes require payment; action alone is not revenue.</li><li><strong>BR-80</strong>: Use precise monetary arithmetic and existing currency rules; show asOf for MRR and the reporting interval for receipts.</li><li><strong>BR-65</strong>: Reporting stores timestamps in UTC and supports UTC or Asia/Ho_Chi_Minh (default). Resolve date boundaries and daily/monthly buckets in the selected timezone; include timezone in responses, exports and cache keys.</li><li><strong>BR-82</strong>: System roles are ADMIN and USER only. Agency/Workspace membership roles are managed separately. Subscription plan identifiers come from the existing catalog (currently BASIC, PRO, ENTERPRISE), not a second hardcoded catalog.</li><li><strong>BR-16</strong>: Audit financial queries and exports.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>User does not possess ADMIN role permissions → Display: MSG39</li><li>Selected date filtering interval contains no transaction records → Display: MSG122</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>Admin opens SCR-ADM-10 and selects period, timezone and optional catalog plan.</li><li>Verify ADMIN and resolve reporting boundaries.</li><li>Calculate current normalized subscription MRR and ARR independently of receipt dates.</li><li>Aggregate successful payments and refunds in the selected period; split subscription/AI Credit and compute net receipts.</li><li>Render values with asOf, period and timezone; preserve these parameters for PDF export.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>2.a1: If user does not possess ADMIN role, system blocks access and displays MSG39.</li><li>3.a1: If selected date range contains no transactions, system displays MSG122.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>Revenue metrics and transaction histories are rendered accurately on the dashboard.</li><li>Reconciled financial data is staged and ready for PDF report export upon administrative request.</li></ul>",14)])])}const m=t(r,[["render",a]]);export{g as __pageData,m as default};
